<?php
require_once __DIR__ . '/crud/bootstrap.php';
$conn=conecta();$start=post('datai',date('Y-m-01'));$end=post('dataf',date('Y-m-d'));$omit=isset($_POST['cancelados']);$orders=[];
if($_SERVER['REQUEST_METHOD']==='POST'){$sql='SELECT c.id_compra,c.status,c.data,u.nome,u.email FROM compra c LEFT JOIN usuario u ON u.id_usuario=c.fk_usuario WHERE c.data::date BETWEEN :start AND :end'.($omit?' AND c.status <> \'cancelado\'':'').' ORDER BY c.data DESC';$stmt=$conn->prepare($sql);$stmt->execute([':start'=>$start,':end'=>$end]);$orders=$stmt->fetchAll(PDO::FETCH_ASSOC);}
adminHeader('Monitor de vendas');?><main class="admin-page"><h1>Monitor de vendas</h1><div class="admin-card"><form class="admin-actions" method="post"><label>De <input type="date" name="datai" value="<?=e($start)?>"></label><label>Até <input type="date" name="dataf" value="<?=e($end)?>"></label><label><input type="checkbox" name="cancelados" <?= $omit?'checked':''?>> Omitir cancelados</label><button class="admin-button">Filtrar</button></form></div><table class="admin-table"><tr><th>Compra</th><th>Data</th><th>Status</th><th>Usuário</th><th>Itens</th><th>Total</th></tr><?php foreach($orders as $order):$stmt=$conn->prepare('SELECT p.nome,cp.quantidade,cp.valor_unitario,(cp.quantidade*cp.valor_unitario) subtotal FROM compra_produto cp JOIN produto p ON p.id_produto=cp.fk_produto WHERE cp.fk_compra=:id ORDER BY p.nome');$stmt->execute([':id'=>$order['id_compra']]);$items=$stmt->fetchAll(PDO::FETCH_ASSOC);$total=0;?><tr><td><?=e($order['id_compra'])?></td><td><?=date('d/m/Y H:i',strtotime($order['data']))?></td><td><?=e($order['status'])?></td><td><?=e($order['nome'])?><br><?=e($order['email'])?></td><td class="report-items"><?php foreach($items as $item):$total+=(float)$item['subtotal'];?><div><?=e($item['nome'])?> (<?=$item['quantidade']?> × R$ <?=number_format((float)$item['valor_unitario'],2,',','.')?> = R$ <?=number_format((float)$item['subtotal'],2,',','.')?>)</div><?php endforeach;?></td><td>R$ <?=number_format($total,2,',','.')?></td></tr><?php endforeach;?></table></main><?php adminFooter();?>
